window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["autoalchemy"]={html:"<div class=\"own-autoalchemy\" id=\"aa-app\">\n  <!-- ── TOPBAR ─────────────────────────────────────────────────────── -->\n  <header class=\"aa-topbar\">\n    <div class=\"aa-brand\">\n      <span class=\"aa-brand-mark\" aria-hidden=\"true\">NW</span>\n      Northwind — Operations Review\n    </div>\n    <div class=\"aa-topbar-right\">\n      <span class=\"aa-status-pill\"><span class=\"aa-status-dot\" aria-hidden=\"true\"></span>Reporting live</span>\n      <div class=\"aa-theme-toggle\" role=\"group\" aria-label=\"Theme\">\n        <button type=\"button\" data-aa-theme=\"light\" class=\"on\">Light</button>\n        <button type=\"button\" data-aa-theme=\"dark\">Dark</button>\n      </div>\n      <button type=\"button\" class=\"aa-print-btn\" data-aa-print>Export PDF</button>\n    </div>\n  </header>\n\n  <div class=\"aa-shell\">\n    <!-- ── SIDEBAR ─────────────────────────────────────────────────── -->\n    <nav class=\"aa-sidebar\" aria-label=\"Report sections\">\n      <a class=\"aa-nav-item on\" href=\"#aa-s01\" data-aa-nav=\"aa-s01\"><span class=\"aa-nav-num\">01</span>TL;DR</a>\n      <a class=\"aa-nav-item\" href=\"#aa-s02\" data-aa-nav=\"aa-s02\"><span class=\"aa-nav-num\">02</span>What shipped</a>\n      <a class=\"aa-nav-item\" href=\"#aa-s03\" data-aa-nav=\"aa-s03\"><span class=\"aa-nav-num\">03</span>Regions</a>\n      <a class=\"aa-nav-item\" href=\"#aa-s04\" data-aa-nav=\"aa-s04\"><span class=\"aa-nav-num\">04</span>Architecture</a>\n      <a class=\"aa-nav-item\" href=\"#aa-s05\" data-aa-nav=\"aa-s05\"><span class=\"aa-nav-num\">05</span>Decisions</a>\n      <a class=\"aa-nav-item\" href=\"#aa-s06\" data-aa-nav=\"aa-s06\"><span class=\"aa-nav-num\">06</span>Defects + next</a>\n      <a class=\"aa-nav-item\" href=\"#aa-s07\" data-aa-nav=\"aa-s07\"><span class=\"aa-nav-num\">07</span>Design</a>\n      <a class=\"aa-nav-item\" href=\"#aa-s08\" data-aa-nav=\"aa-s08\"><span class=\"aa-nav-num\">08</span>Process log</a>\n      <a class=\"aa-nav-item\" href=\"#aa-s09\" data-aa-nav=\"aa-s09\"><span class=\"aa-nav-num\">09</span>Runbook</a>\n      <div class=\"aa-sidebar-foot\">\n        <p>Northwind<br>Operations analytics<br>Quarterly review · Q3 2026</p>\n      </div>\n    </nav>\n\n    <!-- ── CONTENT ─────────────────────────────────────────────────── -->\n    <main class=\"aa-content\">\n      <!-- 01 TL;DR -->\n      <section id=\"aa-s01\" class=\"aa-sec\">\n        <div class=\"aa-eyebrow\"><span class=\"aa-eyebrow-num\">01</span>TL;DR</div>\n        <div class=\"aa-hero aa-hero-pop\">\n          <div class=\"aa-hero-status\">\n            <span class=\"aa-pill aa-pill-live\">● Healthy</span>\n            <span class=\"aa-pill aa-pill-hot\">Northwind 4.0 cutover</span>\n            <span class=\"aa-pill\">Run 2026-Q3</span>\n          </div>\n          <h1>Regional throughput up <span class=\"aa-url\">12.4%</span> after the 4.0 roll-out</h1>\n          <p class=\"aa-lede\">All six regions are reporting against the same operations model for the first time. Dashboards rebuilt on the shared metric layer; the nightly roll-up now lands before 06:00 local in every region.</p>\n          <div class=\"aa-first-step\">\n            <b>Do this first:</b> open the <span class=\"aa-mono\">Regional throughput</span> board, set the range to <b>Last 90 days</b>, and compare APAC against the plan — it is the region that moved most.\n          </div>\n        </div>\n\n        <div class=\"aa-kpi-rail\">\n          <div class=\"aa-kpi aa-kpi--hero\">\n            <div class=\"aa-kpi-label\">Units / day</div>\n            <div class=\"aa-kpi-value\">184<span class=\"aa-kpi-unit\">K</span></div>\n            <div class=\"aa-kpi-sub\">network total · 12.4% over Q2</div>\n          </div>\n          <div class=\"aa-kpi\">\n            <div class=\"aa-kpi-label\">Regions live</div>\n            <div class=\"aa-kpi-value\">6<span class=\"aa-kpi-unit\">/6</span></div>\n            <div class=\"aa-kpi-sub\">single metric layer</div>\n          </div>\n          <div class=\"aa-kpi\">\n            <div class=\"aa-kpi-label\">Dashboards</div>\n            <div class=\"aa-kpi-value\">41</div>\n            <div class=\"aa-kpi-sub\">migrated off legacy</div>\n          </div>\n          <div class=\"aa-kpi\">\n            <div class=\"aa-kpi-label\">On-time roll-up</div>\n            <div class=\"aa-kpi-value\">99.2<span class=\"aa-kpi-unit\">%</span></div>\n            <div class=\"aa-kpi-sub\">before 06:00 local</div>\n          </div>\n          <div class=\"aa-kpi\">\n            <div class=\"aa-kpi-label\">Cost / seat</div>\n            <div class=\"aa-kpi-value aa-kpi-tight\">$4.10</div>\n            <div class=\"aa-kpi-sub\">down from $5.60</div>\n          </div>\n          <div class=\"aa-kpi\">\n            <div class=\"aa-kpi-label\">Query p95</div>\n            <div class=\"aa-kpi-value\">840<span class=\"aa-kpi-unit\">ms</span></div>\n            <div class=\"aa-kpi-sub\">was 2.9s pre-4.0</div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 02 What shipped -->\n      <section id=\"aa-s02\" class=\"aa-sec\">\n        <div class=\"aa-eyebrow\"><span class=\"aa-eyebrow-num\">02</span>What shipped</div>\n        <h2 class=\"aa-t-section\">Operations surface vs. the original ask</h2>\n        <div class=\"aa-table-wrap\">\n          <table>\n            <thead><tr><th>Area</th><th>Ask (scope IN)</th><th>Status</th></tr></thead>\n            <tbody>\n              <tr><td><b>Metric layer</b></td><td>One governed definition per operations metric, region-agnostic</td><td><span class=\"aa-chip aa-chip-ok\">✓ shipped</span></td></tr>\n              <tr><td><b>Regional throughput</b></td><td>Live board, 6 regions, plan vs. actual, drill to site</td><td><span class=\"aa-chip aa-chip-ok\">✓ shipped</span> — reconciled to ±0.3%</td></tr>\n              <tr><td><b>Pricing tiers</b></td><td>Tier editor, margin guardrails, effective-date history</td><td><span class=\"aa-chip aa-chip-ok\">✓ shipped</span> — 4 tiers published</td></tr>\n              <tr><td><b>Inventory aging</b></td><td>Buckets 0-30 / 31-90 / 90+, site roll-up</td><td><span class=\"aa-chip aa-chip-partial\">◐ partial</span> — 2 regions pending source fix</td></tr>\n              <tr><td><b>Nightly roll-up</b></td><td>Shared orchestration, per-region SLA 06:00 local</td><td><span class=\"aa-chip aa-chip-ok\">✓ shipped</span> — 99.2% on time</td></tr>\n              <tr><td><b>Alerting</b></td><td>Threshold + anomaly alerts into the ops channel</td><td><span class=\"aa-chip aa-chip-ok\">✓ shipped</span></td></tr>\n              <tr><td><b>Forecasting</b></td><td>13-week horizon per region</td><td><span class=\"aa-chip aa-chip-info\">v4.1</span> — scope-out this cut</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </section>\n\n      <!-- 03 Regions -->\n      <section id=\"aa-s03\" class=\"aa-sec\">\n        <div class=\"aa-eyebrow\"><span class=\"aa-eyebrow-num\">03</span>Regional throughput</div>\n        <h2 class=\"aa-t-section\">Where the volume actually is</h2>\n        <p class=\"aa-lede\">Every row below is computed from the same nightly snapshot — plan, actual, and variance use one definition of a \"unit\".</p>\n        <div class=\"aa-table-wrap\">\n          <table>\n            <thead><tr><th>Region</th><th class=\"aa-num-col\">Plan</th><th class=\"aa-num-col\">Actual</th><th class=\"aa-num-col\">Var</th><th>Status</th></tr></thead>\n            <tbody>\n              <tr><td><b>APAC</b></td><td class=\"aa-td-num\">42.0K</td><td class=\"aa-td-num\">48.6K</td><td class=\"aa-td-num aa-td-accent\">+15.7%</td><td><span class=\"aa-chip aa-chip-ok\">ahead</span></td></tr>\n              <tr><td><b>North America</b></td><td class=\"aa-td-num\">56.0K</td><td class=\"aa-td-num\">59.2K</td><td class=\"aa-td-num aa-td-accent\">+5.7%</td><td><span class=\"aa-chip aa-chip-ok\">ahead</span></td></tr>\n              <tr><td><b>EMEA</b></td><td class=\"aa-td-num\">38.0K</td><td class=\"aa-td-num\">36.1K</td><td class=\"aa-td-num\">−5.0%</td><td><span class=\"aa-chip aa-chip-warn\">watch</span></td></tr>\n              <tr><td><b>LATAM</b></td><td class=\"aa-td-num\">21.0K</td><td class=\"aa-td-num\">22.4K</td><td class=\"aa-td-num aa-td-accent\">+6.7%</td><td><span class=\"aa-chip aa-chip-ok\">ahead</span></td></tr>\n              <tr><td><b>MEA</b></td><td class=\"aa-td-num\">12.0K</td><td class=\"aa-td-num\">10.8K</td><td class=\"aa-td-num\">−10.0%</td><td><span class=\"aa-chip aa-chip-crit\">behind</span></td></tr>\n              <tr><td><b>India</b></td><td class=\"aa-td-num\">15.0K</td><td class=\"aa-td-num\">16.9K</td><td class=\"aa-td-num aa-td-accent\">+12.7%</td><td><span class=\"aa-chip aa-chip-ok\">ahead</span></td></tr>\n            </tbody>\n          </table>\n        </div>\n      </section>\n\n      <!-- 04 Architecture -->\n      <section id=\"aa-s04\" class=\"aa-sec\">\n        <div class=\"aa-eyebrow\"><span class=\"aa-eyebrow-num\">04</span>Architecture as built</div>\n        <h2 class=\"aa-t-section\">The nightly pipeline</h2>\n        <div class=\"aa-pipeline\">\n          <div class=\"aa-pipe-step\"><div class=\"aa-pipe-num\">1</div><h4>Source systems</h4><p>Regional WMS + POS exports land in the staging area by 01:00 local.</p><span class=\"aa-pipe-arrow\" aria-hidden=\"true\">→</span></div>\n          <div class=\"aa-pipe-step\"><div class=\"aa-pipe-num\">2</div><h4>Ingest + validate</h4><p>Schema checks, dedupe, and a per-region reject report on every run.</p><span class=\"aa-pipe-arrow\" aria-hidden=\"true\">→</span></div>\n          <div class=\"aa-pipe-step\"><div class=\"aa-pipe-num\">3</div><h4>Metric layer</h4><p>Governed definitions compute throughput, aging, and margin once.</p><span class=\"aa-pipe-arrow\" aria-hidden=\"true\">→</span></div>\n          <div class=\"aa-pipe-step\"><div class=\"aa-pipe-num\">4</div><h4>Roll-up</h4><p>Site → region → network, published to the serving store before 06:00.</p></div>\n        </div>\n\n        <h3 class=\"aa-sub-h\">Where v4.0 diverged from the plan — and why</h3>\n        <ul class=\"aa-delta-list\">\n          <li><b>Orchestration:</b> moved to a single shared scheduler instead of one per region; per-region SLAs are now enforced by a single dependency graph, which is what made the 99.2% on-time figure possible.</li>\n          <li><b>Inventory aging:</b> kept the manual source patch for two regions rather than blocking the cut-over — tracked as D-2 below.</li>\n          <li><b>Metric storage:</b> a governed view layer rather than a physical warehouse table; query p95 fell more than projected as a result.</li>\n          <li><b>Alerting:</b> shipped to the ops channel directly, not email — email batching hid the first 20 minutes of incidents.</li>\n        </ul>\n      </section>\n\n      <!-- 05 Decisions -->\n      <section id=\"aa-s05\" class=\"aa-sec\">\n        <div class=\"aa-eyebrow\"><span class=\"aa-eyebrow-num\">05</span>Decisions still open</div>\n        <h2 class=\"aa-t-section\">What needs a call</h2>\n        <div class=\"aa-alert aa-alert-crit\">\n          <div class=\"aa-alert-title\">⚠ Forecasting horizon — blocked</div>\n          <p>The 13-week forecast needs a seasonal model per region, but two regions (MEA, EMEA) have fewer than 15 months of clean history. <b>Fix:</b> either ship a 6-week horizon for those two, or backfill from the legacy monthly extracts. A decision is needed before the v4.1 scope freeze.</p>\n        </div>\n        <div class=\"aa-table-wrap\">\n          <table>\n            <thead><tr><th>ID</th><th>Decision</th><th>Built as</th></tr></thead>\n            <tbody>\n              <tr><td class=\"aa-td-accent\">OD1</td><td>Metric ownership</td><td>Governed layer, definitions versioned with the model — not per-dashboard.</td></tr>\n              <tr><td class=\"aa-td-accent\">OD2</td><td>Roll-up trigger</td><td>Event on ingest completion, with a 05:30 local hard deadline.</td></tr>\n              <tr><td class=\"aa-td-accent\">OD3</td><td>Aging buckets</td><td>0-30 / 31-90 / 90+ as specified; no regional custom buckets.</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </section>\n\n      <!-- 06 Defects -->\n      <section id=\"aa-s06\" class=\"aa-sec\">\n        <div class=\"aa-eyebrow\"><span class=\"aa-eyebrow-num\">06</span>Known defects + next five</div>\n        <h2 class=\"aa-t-section\">What's left</h2>\n        <div class=\"aa-table-wrap\">\n          <table>\n            <thead><tr><th class=\"aa-num-col\">#</th><th>Defect</th><th>Where</th><th>Severity</th></tr></thead>\n            <tbody>\n              <tr><td class=\"aa-td-num\">1</td><td>Inventory aging shows zero for sites missing a source timestamp</td><td>aging roll-up</td><td><span class=\"aa-chip aa-chip-warn\">data gap</span></td></tr>\n              <tr><td class=\"aa-td-num\">2</td><td>Two regions still on the manual source patch</td><td>ingest / EMEA, MEA</td><td><span class=\"aa-chip aa-chip-crit\">blocking v4.1</span></td></tr>\n              <tr><td class=\"aa-td-num\">3</td><td>Pricing tier history omits the superseded tier name</td><td>tier editor</td><td><span class=\"aa-chip aa-chip-info\">cosmetic</span></td></tr>\n              <tr><td class=\"aa-td-num\">4</td><td>Alert test button sends a live notification with no sample flag</td><td>alerting</td><td><span class=\"aa-chip aa-chip-warn\">noisy</span></td></tr>\n            </tbody>\n          </table>\n        </div>\n        <h3 class=\"aa-sub-h\">Next five things</h3>\n        <ol class=\"aa-next-list\">\n          <li>Land the two-region source fix (D-2) — it gates the only defect marked blocking.</li>\n          <li>Resolve the forecasting-horizon decision (OD, §05) before the v4.1 freeze.</li>\n          <li>Backfill the missing aging timestamps and re-run the D-1 reconciliation.</li>\n          <li>Flag alert-test notifications as samples so they can't page the on-call.</li>\n          <li>Publish the metric-definition changelog alongside the release notes.</li>\n        </ol>\n      </section>\n\n      <!-- 07 Design -->\n      <section id=\"aa-s07\" class=\"aa-sec\">\n        <div class=\"aa-eyebrow\"><span class=\"aa-eyebrow-num\">07</span>Design</div>\n        <h2 class=\"aa-t-section\">One grammar, two surfaces</h2>\n        <p class=\"aa-lede\">The review document and the operations dashboard share a single token set: warm paper, hard offset shadows, one orange accent, and numbers set apart in a mono display face.</p>\n        <div class=\"aa-two-col\">\n          <div class=\"aa-card-flat\">\n            <div class=\"aa-card-head\">Document surface</div>\n            <p>Reading is calm: warm paper, a faint dot grid, and orange reserved for the one thing that needs attention. Numbers run in a pixel/mono face so a dense page still scans.</p>\n          </div>\n          <div class=\"aa-card-flat\">\n            <div class=\"aa-card-head\">Dashboard surface</div>\n            <p>Same tokens, denser grid. KPI tiles lift with a hard shadow, status colors stay strictly semantic — green / amber / red for ok / warn / crit and nothing else.</p>\n          </div>\n        </div>\n        <h3 class=\"aa-sub-h\">Two themes, one grammar</h3>\n        <div class=\"aa-theme-swatch-row\">\n          <div class=\"aa-theme-swatch\">\n            <div class=\"aa-theme-swatch-bar\"><span class=\"aa-sw-paper\" aria-hidden=\"true\"></span><span class=\"aa-sw-accent\" aria-hidden=\"true\"></span><span class=\"aa-sw-ink\" aria-hidden=\"true\"></span></div>\n            <div class=\"aa-theme-swatch-label\">Light<small>default · paper</small></div>\n          </div>\n          <div class=\"aa-theme-swatch\">\n            <div class=\"aa-theme-swatch-bar\"><span class=\"aa-sw-dark\" aria-hidden=\"true\"></span><span class=\"aa-sw-accent\" aria-hidden=\"true\"></span><span class=\"aa-sw-black\" aria-hidden=\"true\"></span></div>\n            <div class=\"aa-theme-swatch-label\">Dark<small>ink shadows go black</small></div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 08 Process log -->\n      <section id=\"aa-s08\" class=\"aa-sec\">\n        <div class=\"aa-eyebrow\"><span class=\"aa-eyebrow-num\">08</span>Process log</div>\n        <h2 class=\"aa-t-section\">How the quarter ran</h2>\n        <ul class=\"aa-delta-list\">\n          <li><b>Weeks 1-3:</b> metric-definition workshops with each region; the definitional disagreements surfaced here, not in the build.</li>\n          <li><b>Weeks 4-8:</b> shared pipeline built and shadow-run alongside the legacy roll-up for four weeks.</li>\n          <li><b>Week 9:</b> dashboards migrated region by region, each reconciled to ±0.3% before the next started.</li>\n          <li><b>Week 10:</b> cut-over, legacy roll-up retired; the first all-region morning report published.</li>\n        </ul>\n        <div class=\"aa-alert aa-alert-warn\">\n          <div class=\"aa-alert-title\">⚠ A silent zero passed every validation check</div>\n          <p>One region reported a source extract with an empty inventory file. The schema was valid and the row count non-zero, so it passed; only the aging board's zero-total caught it. A per-region volume floor is now part of the ingest gate.</p>\n        </div>\n      </section>\n\n      <!-- 09 Runbook -->\n      <section id=\"aa-s09\" class=\"aa-sec\">\n        <div class=\"aa-eyebrow\"><span class=\"aa-eyebrow-num\">09</span>Runbook pointers</div>\n        <h2 class=\"aa-t-section\">Where to look</h2>\n        <div class=\"aa-table-wrap\">\n          <table>\n            <thead><tr><th>Topic</th><th>File</th></tr></thead>\n            <tbody>\n              <tr><td>Metric definitions + version history</td><td><code>docs/metrics/DEFINITIONS.md</code></td></tr>\n              <tr><td>Per-region ingest config and volume floors</td><td><code>pipelines/regions/*.yaml</code></td></tr>\n              <tr><td>Roll-up SLA + on-call escalation path</td><td><code>docs/runbook/ROLLUP.md</code> §4</td></tr>\n              <tr><td>Pricing tier change procedure</td><td><code>docs/runbook/PRICING.md</code></td></tr>\n            </tbody>\n          </table>\n        </div>\n      </section>\n\n      <!-- Footer -->\n      <div class=\"aa-footer\">\n        <div class=\"aa-eyebrow\" style=\"margin-bottom:14px\">Files index</div>\n        <ul class=\"aa-file-index\">\n          <li><code>docs/reviews/2026-Q3-ops-review.md</code> — this document</li>\n          <li><code>docs/metrics/DEFINITIONS.md</code> — governed metric layer</li>\n          <li><code>docs/runbook/ROLLUP.md</code> — nightly pipeline runbook</li>\n          <li><code>pipelines/regions/*.yaml</code> — ingest config</li>\n          <li><code>docs/runbook/PRICING.md</code> — tier change procedure</li>\n        </ul>\n      </div>\n    </main>\n  </div>\n</div>\n",css:"/* ══ AUTOALCHEMY — the review-document grammar, ported for showcase.html ════\n   Ported from the AutoAlchemy Hub owner-review single-file HTML (warm paper,\n   dot-grid texture, hard offset \"sticker\" shadows, Outfit prose + Doto numbers,\n   one loud orange accent, numbered sidebar with scroll-spy). Everything is\n   scoped under `.own-autoalchemy`; the fixed full-viewport texture becomes a\n   background on the root so it survives the showcase frame, and the single\n   900px width media query becomes `@container frame`. */\n\n.own-autoalchemy {\n  --accent: #FF6B1A;\n  --accent-2: #E85B10;\n  --accent-ink: #B0470C;\n  --accent-soft: rgba(255, 107, 26, .12);\n  --accent-tint: rgba(255, 107, 26, .07);\n  --paper-0: #FBF9F4;\n  --paper-1: #F2EFE8;\n  --paper-2: #E8E3D8;\n  --paper-3: #DED8CB;\n  --ink: #1C1A16;\n  --ink-2: #57534A;\n  --ink-3: #8B8678;\n  --line: #DED8CB;\n  --line-2: #E9E4D9;\n  --status-ok: #5B7A3F;\n  --status-warn: #B8801F;\n  --status-crit: #C0432C;\n  --status-info: #4A6B7A;\n  --ok-tint: rgba(91, 122, 63, .12);\n  --warn-tint: rgba(184, 128, 31, .12);\n  --crit-tint: rgba(192, 67, 44, .12);\n  --info-tint: rgba(74, 107, 122, .12);\n  --shadow-color: var(--ink);\n  --sidebar-w: 218px;\n  --content-max: 1160px;\n\n  --prose: 'Outfit', system-ui, -apple-system, sans-serif;\n  --data: 'Doto', 'JetBrains Mono', ui-monospace, monospace;\n\n  position: relative;\n  background-color: var(--paper-0);\n  background-image:\n    radial-gradient(60% 100% at 30% 0%, var(--accent-tint), transparent 70%),\n    radial-gradient(circle, var(--ink) 1px, transparent 1px);\n  background-size: 100% 420px, 6px 6px;\n  background-repeat: no-repeat, repeat;\n  background-position: top left, 0 0;\n  color: var(--ink);\n  font-family: var(--prose);\n  font-size: 13px;\n  line-height: 1.55;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n}\n\n.own-autoalchemy *,\n.own-autoalchemy *::before,\n.own-autoalchemy *::after { box-sizing: border-box; }\n\n.own-autoalchemy ::selection { background: var(--accent-soft); }\n\n.own-autoalchemy :focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n  border-radius: 3px;\n}\n\n.own-autoalchemy .aa-mono,\n.own-autoalchemy .aa-td-num,\n.own-autoalchemy .aa-td-accent,\n.own-autoalchemy .aa-kpi-value,\n.own-autoalchemy .aa-nav-num,\n.own-autoalchemy .aa-eyebrow-num,\n.own-autoalchemy .aa-pipe-num { font-family: var(--data); }\n\n/* ── Topbar ──────────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-topbar {\n  position: sticky;\n  top: 68px; /* clears the 56px showcase toolbar */\n  z-index: 100;\n  min-height: 56px;\n  background: var(--paper-1);\n  border-bottom: 1.5px solid var(--ink);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 0 20px;\n}\n.own-autoalchemy .aa-brand {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-weight: 800;\n  font-size: 15px;\n  letter-spacing: -.01em;\n  min-width: 0;\n}\n.own-autoalchemy .aa-brand-mark {\n  width: 26px; height: 26px; flex: none;\n  background: var(--accent);\n  color: #fff;\n  display: flex; align-items: center; justify-content: center;\n  font-family: var(--data); font-weight: 900; font-size: 11px;\n  border-radius: 2px;\n  border: 1.5px solid var(--ink);\n}\n.own-autoalchemy .aa-topbar-right { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: flex-end; }\n.own-autoalchemy .aa-status-pill {\n  display: inline-flex; align-items: center; gap: 6px;\n  padding: 5px 10px;\n  border: 1.5px solid var(--status-ok);\n  background: var(--ok-tint);\n  color: var(--status-ok);\n  border-radius: 2px;\n  font-weight: 700; font-size: 11px;\n  letter-spacing: .08em; text-transform: uppercase;\n  white-space: nowrap;\n}\n.own-autoalchemy .aa-status-dot {\n  width: 6px; height: 6px; border-radius: 50%;\n  background: var(--status-ok);\n  animation: aa-pulse 2s infinite;\n}\n.own-autoalchemy .aa-theme-toggle {\n  display: flex;\n  border: 1.5px solid var(--ink);\n  border-radius: 2px;\n  overflow: hidden;\n}\n.own-autoalchemy .aa-theme-toggle button {\n  border: none;\n  background: var(--paper-1);\n  color: var(--ink-2);\n  padding: 6px 11px;\n  font-family: var(--prose);\n  font-weight: 600; font-size: 11px; letter-spacing: .05em;\n  cursor: pointer;\n}\n.own-autoalchemy .aa-theme-toggle button.on { background: var(--accent); color: #fff; }\n.own-autoalchemy .aa-print-btn {\n  border: 1.5px solid var(--ink);\n  background: var(--paper-1);\n  color: var(--ink);\n  padding: 6px 12px;\n  border-radius: 2px;\n  font-family: var(--prose);\n  font-weight: 600; font-size: 11px;\n  cursor: pointer;\n  box-shadow: 3px 3px 0 0 var(--shadow-color);\n  transition: transform .12s ease, box-shadow .12s ease;\n}\n.own-autoalchemy .aa-print-btn:hover { transform: translate(-1px, -1px); box-shadow: 4px 4px 0 0 var(--shadow-color); }\n.own-autoalchemy .aa-print-btn:active { transform: translate(1px, 1px); box-shadow: 1px 1px 0 0 var(--shadow-color); }\n\n/* ── Shell ────────────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-shell {\n  display: flex;\n  align-items: flex-start;\n  max-width: 1440px;\n  margin: 0 auto;\n}\n.own-autoalchemy .aa-sidebar {\n  width: var(--sidebar-w);\n  flex-shrink: 0;\n  position: sticky;\n  top: 124px; /* topbar (68+56) — sidebar sticks below the pinned topbar */\n  align-self: flex-start;\n  max-height: calc(100vh - 124px);\n  overflow-y: auto;\n  background: var(--paper-1);\n  border-right: 1.5px solid var(--ink);\n  padding: 18px 0;\n  scrollbar-width: thin;\n}\n.own-autoalchemy .aa-nav-item {\n  display: flex; align-items: center; gap: 10px;\n  padding: 9px 20px;\n  text-decoration: none;\n  color: var(--ink-2);\n  font-size: 12.5px; font-weight: 600;\n  border-left: 3px solid transparent;\n  cursor: pointer;\n  white-space: nowrap;\n}\n.own-autoalchemy .aa-nav-item .aa-nav-num {\n  font-size: 10px; font-weight: 700; letter-spacing: .06em;\n  color: var(--ink-3);\n  min-width: 16px;\n}\n.own-autoalchemy .aa-nav-item:hover { background: var(--paper-2); }\n.own-autoalchemy .aa-nav-item.on { background: var(--accent-tint); color: var(--ink); border-left-color: var(--accent); }\n.own-autoalchemy .aa-nav-item.on .aa-nav-num { color: var(--accent-ink); }\n.own-autoalchemy .aa-sidebar-foot {\n  padding: 16px 20px 0;\n  margin-top: 12px;\n  border-top: 1px solid var(--line);\n}\n.own-autoalchemy .aa-sidebar-foot p { font-size: 10.5px; color: var(--ink-3); line-height: 1.6; margin: 0; }\n\n.own-autoalchemy .aa-content {\n  flex: 1;\n  min-width: 0;\n  max-width: var(--content-max);\n  padding: 36px 32px 90px;\n}\n.own-autoalchemy .aa-sec { margin-bottom: 48px; scroll-margin-top: 140px; }\n\n.own-autoalchemy .aa-eyebrow {\n  font-size: 11px; font-weight: 700;\n  letter-spacing: .22em; text-transform: uppercase;\n  color: var(--accent-ink);\n  display: flex; align-items: center; gap: 8px;\n  margin-bottom: 8px;\n}\n.own-autoalchemy .aa-t-section {\n  font-size: 20px; font-weight: 700;\n  letter-spacing: -.01em;\n  margin: 0 0 18px;\n}\n.own-autoalchemy .aa-sub-h { font-size: 14px; font-weight: 700; margin: 24px 0 10px; color: var(--ink); }\n.own-autoalchemy .aa-lede { color: var(--ink-2); font-size: 13.5px; max-width: 70ch; margin: 0 0 14px; }\n.own-autoalchemy p { margin: 0 0 10px; }\n.own-autoalchemy code {\n  font-family: var(--data);\n  font-size: 11.5px;\n  background: var(--paper-2);\n  padding: 1px 5px;\n  border-radius: 2px;\n}\n\n/* ── Hero ─────────────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-hero {\n  background: var(--paper-2);\n  border: 1.5px solid var(--ink);\n  border-radius: 3px;\n  padding: 26px 28px;\n  margin-bottom: 24px;\n}\n.own-autoalchemy .aa-hero-pop { box-shadow: 6px 6px 0 0 var(--shadow-color); }\n.own-autoalchemy .aa-hero-status { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; }\n.own-autoalchemy .aa-hero h1 { font-size: 24px; font-weight: 800; letter-spacing: -.01em; margin: 0 0 10px; }\n.own-autoalchemy .aa-url { font-family: var(--data); font-size: 22px; font-weight: 600; color: var(--accent-ink); }\n.own-autoalchemy .aa-first-step {\n  margin-top: 16px;\n  padding: 14px 16px;\n  background: var(--paper-0);\n  border: 1px solid var(--line);\n  border-radius: 2px;\n  font-size: 13px;\n}\n.own-autoalchemy .aa-first-step b { color: var(--accent-ink); }\n.own-autoalchemy .aa-first-step .aa-mono { font-family: var(--data); font-size: 12px; }\n\n/* ── Pills ────────────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-pill {\n  display: inline-flex; align-items: center; gap: 6px;\n  padding: 4px 10px;\n  border: 1px solid var(--ink);\n  border-radius: 2px;\n  font-size: 11px; font-weight: 600;\n  letter-spacing: .14em; text-transform: uppercase;\n  color: var(--ink-2);\n}\n.own-autoalchemy .aa-pill-hot { background: var(--accent-soft); color: var(--accent-ink); border-color: var(--accent); font-weight: 700; }\n.own-autoalchemy .aa-pill-live { background: var(--ok-tint); color: var(--status-ok); border-color: var(--status-ok); }\n\n/* ── KPI rail ─────────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-kpi-rail {\n  display: grid;\n  grid-template-columns: 1.25fr 1fr 1fr 1fr 1fr 1fr;\n  gap: 12px;\n}\n.own-autoalchemy .aa-kpi {\n  background: var(--paper-1);\n  border: 1.5px solid var(--ink);\n  border-radius: 3px;\n  padding: 16px;\n  box-shadow: 3px 3px 0 0 var(--shadow-color);\n  display: flex; flex-direction: column; gap: 6px;\n  min-width: 0;\n}\n.own-autoalchemy .aa-kpi--hero { background: var(--paper-2); box-shadow: none; }\n.own-autoalchemy .aa-kpi-label {\n  font-size: 10px; font-weight: 700;\n  letter-spacing: .1em; text-transform: uppercase;\n  color: var(--ink-3);\n}\n.own-autoalchemy .aa-kpi-value { font-size: 28px; font-weight: 700; line-height: 1; color: var(--ink); }\n.own-autoalchemy .aa-kpi--hero .aa-kpi-value { font-size: 38px; font-weight: 900; color: var(--accent-ink); }\n.own-autoalchemy .aa-kpi-unit { font-size: 15px; }\n.own-autoalchemy .aa-kpi-tight { font-size: 22px; }\n.own-autoalchemy .aa-kpi-sub { font-size: 10.5px; color: var(--ink-3); }\n\n/* ── Tables ───────────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-table-wrap {\n  overflow-x: auto;\n  border: 1.5px solid var(--ink);\n  border-radius: 3px;\n  box-shadow: 3px 3px 0 0 var(--shadow-color);\n  background: var(--paper-1);\n}\n.own-autoalchemy table { width: 100%; border-collapse: collapse; font-size: 12.5px; }\n.own-autoalchemy thead th {\n  background: var(--paper-2);\n  text-align: left;\n  padding: 9px 12px;\n  font-size: 10.5px; font-weight: 600;\n  letter-spacing: .1em; text-transform: uppercase;\n  color: var(--ink-3);\n  border-bottom: 1.5px solid var(--ink);\n  white-space: nowrap;\n}\n.own-autoalchemy tbody td { padding: 10px 12px; border-bottom: 1px solid var(--line); vertical-align: top; }\n.own-autoalchemy tbody tr:last-child td { border-bottom: none; }\n.own-autoalchemy tbody tr:hover { background: var(--paper-2); }\n.own-autoalchemy .aa-td-num { font-weight: 600; white-space: nowrap; }\n.own-autoalchemy .aa-td-accent { font-weight: 700; color: var(--accent-ink); white-space: nowrap; }\n.own-autoalchemy .aa-num-col { text-align: right; }\n\n/* ── Status chips ─────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-chip {\n  display: inline-flex; align-items: center; gap: 5px;\n  padding: 3px 8px;\n  border-radius: 2px;\n  font-size: 10.5px; font-weight: 700;\n  letter-spacing: .05em; text-transform: uppercase;\n  white-space: nowrap;\n}\n.own-autoalchemy .aa-chip-ok { background: var(--ok-tint); color: var(--status-ok); }\n.own-autoalchemy .aa-chip-warn { background: var(--warn-tint); color: var(--status-warn); }\n.own-autoalchemy .aa-chip-crit { background: var(--crit-tint); color: var(--status-crit); }\n.own-autoalchemy .aa-chip-info { background: var(--info-tint); color: var(--status-info); }\n.own-autoalchemy .aa-chip-partial { background: var(--accent-soft); color: var(--accent-ink); }\n\n/* ── Alerts ───────────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-alert { border-radius: 2px; padding: 14px 16px; border: 1.5px solid; margin-bottom: 14px; }\n.own-autoalchemy .aa-alert-title {\n  font-size: 11px; font-weight: 700;\n  letter-spacing: .1em; text-transform: uppercase;\n  margin-bottom: 6px;\n  display: flex; align-items: center; gap: 7px;\n}\n.own-autoalchemy .aa-alert-crit { background: var(--crit-tint); border-color: var(--status-crit); color: var(--status-crit); }\n.own-autoalchemy .aa-alert-warn { background: var(--warn-tint); border-color: var(--status-warn); color: var(--status-warn); }\n.own-autoalchemy .aa-alert p { color: var(--ink); font-size: 12.5px; margin: 0; }\n\n/* ── Layout helpers ────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }\n.own-autoalchemy .aa-card-flat {\n  background: var(--paper-1);\n  border: 1px solid var(--line);\n  border-radius: 3px;\n  padding: 20px;\n}\n.own-autoalchemy .aa-card-head {\n  display: flex; align-items: center; gap: 8px;\n  font-size: 11px; font-weight: 600;\n  letter-spacing: .16em; text-transform: uppercase;\n  color: var(--ink-3);\n  margin-bottom: 12px;\n}\n.own-autoalchemy .aa-card-head::before {\n  content: \"\"; width: 8px; height: 8px;\n  background: var(--accent); border-radius: 1px; flex-shrink: 0;\n}\n.own-autoalchemy .aa-card-flat p { margin: 0; }\n\n/* ── Pipeline ─────────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-pipeline {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 12px;\n  position: relative;\n  margin-top: 8px;\n}\n.own-autoalchemy .aa-pipeline::before {\n  content: \"\"; position: absolute;\n  top: 20px; left: 5%; right: 5%; height: 2px;\n  background: var(--line); z-index: 0;\n}\n.own-autoalchemy .aa-pipe-step {\n  position: relative; z-index: 1;\n  background: var(--paper-1);\n  border: 1.5px solid var(--ink);\n  border-radius: 3px;\n  padding: 14px 12px;\n  box-shadow: 3px 3px 0 0 var(--shadow-color);\n}\n.own-autoalchemy .aa-pipe-num {\n  width: 24px; height: 24px;\n  background: var(--ink); color: var(--paper-0);\n  border-radius: 2px;\n  display: flex; align-items: center; justify-content: center;\n  font-weight: 700; font-size: 12px;\n  margin-bottom: 10px;\n}\n.own-autoalchemy .aa-pipe-step h4 { font-size: 12px; font-weight: 700; margin: 0 0 4px; }\n.own-autoalchemy .aa-pipe-step p { font-size: 11px; color: var(--ink-2); margin: 0; }\n.own-autoalchemy .aa-pipe-arrow {\n  position: absolute; top: 14px; right: -9px;\n  font-size: 14px; color: var(--ink-3); z-index: 2;\n}\n\n/* ── Delta + next lists ────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-delta-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.own-autoalchemy .aa-delta-list li {\n  padding: 12px 14px;\n  background: var(--paper-0);\n  border: 1px solid var(--line);\n  border-radius: 2px;\n  font-size: 12.5px;\n}\n.own-autoalchemy .aa-delta-list b { color: var(--accent-ink); }\n.own-autoalchemy .aa-next-list { padding-left: 20px; font-size: 12.5px; color: var(--ink); margin: 0; }\n.own-autoalchemy .aa-next-list li { margin-bottom: 8px; }\n\n/* ── Theme swatches ────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-theme-swatch-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-top: 6px; }\n.own-autoalchemy .aa-theme-swatch { border: 1.5px solid var(--ink); border-radius: 3px; overflow: hidden; box-shadow: 3px 3px 0 0 var(--shadow-color); }\n.own-autoalchemy .aa-theme-swatch-bar { height: 36px; display: flex; }\n.own-autoalchemy .aa-theme-swatch-bar span { flex: 1; }\n.own-autoalchemy .aa-sw-paper { background: #E8E3D8; }\n.own-autoalchemy .aa-sw-dark { background: #242118; }\n.own-autoalchemy .aa-sw-accent { background: #FF6B1A; }\n.own-autoalchemy .aa-sw-ink { background: #1C1A16; }\n.own-autoalchemy .aa-sw-black { background: #000; }\n.own-autoalchemy .aa-theme-swatch-label { padding: 9px 10px; background: var(--paper-1); font-size: 11px; font-weight: 700; }\n.own-autoalchemy .aa-theme-swatch-label small { display: block; font-weight: 400; color: var(--ink-3); font-size: 10px; margin-top: 2px; }\n\n/* ── Footer ────────────────────────────────────────────────────────────────── */\n.own-autoalchemy .aa-footer { border-top: 1.5px solid var(--ink); margin-top: 8px; padding-top: 24px; }\n.own-autoalchemy .aa-file-index { columns: 2; gap: 24px; font-size: 12px; list-style: none; margin: 0; padding: 0; }\n.own-autoalchemy .aa-file-index li { margin-bottom: 6px; break-inside: avoid; }\n\n/* ── Motion ────────────────────────────────────────────────────────────────── */\n@keyframes aa-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }\n@media (prefers-reduced-motion: reduce) {\n  .own-autoalchemy .aa-status-dot { animation: none; }\n  .own-autoalchemy .aa-print-btn { transition: none; }\n}\n\n/* ── Dark theme (same component classes, tokens swap) ─────────────────────── */\n.own-autoalchemy.aa-dark {\n  --paper-0: #1C1A16;\n  --paper-1: #242118;\n  --paper-2: #2C2820;\n  --paper-3: #38342A;\n  --ink: #F2EFE8;\n  --ink-2: #C2BCAE;\n  --ink-3: #8E8A7C;\n  --line: #38342A;\n  --line-2: #2C2820;\n  --accent-ink: #FF8A45;\n  --accent-soft: rgba(255, 107, 26, .18);\n  --accent-tint: rgba(255, 107, 26, .10);\n  --status-ok: #7FA85C;\n  --status-warn: #D6A03E;\n  --status-crit: #DB5C44;\n  --status-info: #6E97A8;\n  --ok-tint: rgba(127, 168, 92, .14);\n  --warn-tint: rgba(214, 160, 62, .14);\n  --crit-tint: rgba(219, 92, 68, .14);\n  --info-tint: rgba(110, 151, 168, .14);\n  --shadow-color: #000000;\n}\n\n/* ── Container-responsive (the source's single 900px cut-over) ───────────── */\n@container frame (max-width: 1100px) {\n  .own-autoalchemy .aa-kpi-rail { grid-template-columns: 1.25fr 1fr 1fr; }\n}\n@container frame (max-width: 900px) {\n  .own-autoalchemy .aa-sidebar { display: none; }\n  .own-autoalchemy .aa-content { padding: 24px 20px 60px; }\n  .own-autoalchemy .aa-kpi-rail { grid-template-columns: 1fr 1fr; }\n  .own-autoalchemy .aa-two-col { grid-template-columns: 1fr; }\n  .own-autoalchemy .aa-pipeline { grid-template-columns: 1fr 1fr; }\n  .own-autoalchemy .aa-theme-swatch-row { grid-template-columns: 1fr 1fr; }\n  .own-autoalchemy .aa-file-index { columns: 1; }\n}\n@container frame (max-width: 760px) {\n  .own-autoalchemy .aa-topbar { flex-wrap: wrap; padding: 8px 16px; }\n  .own-autoalchemy .aa-brand { font-size: 13px; }\n  .own-autoalchemy .aa-hero { padding: 20px 18px; }\n  .own-autoalchemy .aa-hero h1 { font-size: 20px; }\n}\n@container frame (max-width: 430px) {\n  .own-autoalchemy .aa-kpi-rail { grid-template-columns: 1fr; }\n  .own-autoalchemy .aa-pipeline { grid-template-columns: 1fr; }\n  .own-autoalchemy .aa-two-col { grid-template-columns: 1fr; }\n  .own-autoalchemy .aa-theme-swatch-row { grid-template-columns: 1fr; }\n  .own-autoalchemy .aa-status-pill { display: none; }\n}\n"};
/* ══ AUTOALCHEMY — review-document behaviour for showcase.html ════════════
   Registers window.OWN_LAYOUTS['autoalchemy'].init(root). Reproduces the source
   template's three bits of JS: the light/dark theme toggle (token override on the
   root, remembered per layout), the IntersectionObserver scroll-spy that lights
   the numbered sidebar, and the print/export button. init returns a cleanup fn so
   unmounting removes the observer, listeners and any in-flight frame. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['autoalchemy'] = {
    init: function (root) {
      var SECTIONS = ['aa-s01', 'aa-s02', 'aa-s03', 'aa-s04', 'aa-s05', 'aa-s06', 'aa-s07', 'aa-s08', 'aa-s09'];
      var STORE = 'own-autoalchemy-theme';

      var $ = function (sel) { return root.querySelector(sel); };
      var $$ = function (sel) { return Array.prototype.slice.call(root.querySelectorAll(sel)); };

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var observers = [];
      var rafs = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        var o = Object.assign({}, opt || {});
        if (signal) o.signal = signal;
        el.addEventListener(type, fn, o);
      }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }

      /* ── theme toggle ──────────────────────────────────────────────────── */
      function setTheme(t) {
        root.classList.toggle('aa-dark', t === 'dark');
        $$('[data-aa-theme]').forEach(function (b) {
          b.classList.toggle('on', b.getAttribute('data-aa-theme') === t);
        });
        try { localStorage.setItem(STORE, t); } catch (e) { /* ignore */ }
      }
      var saved = null;
      try { saved = localStorage.getItem(STORE); } catch (e) { /* ignore */ }
      if (saved === 'dark') setTheme('dark');

      var toggle = $('.aa-theme-toggle');
      on(toggle, 'click', function (e) {
        var b = e.target.closest('[data-aa-theme]');
        if (!b) return;
        setTheme(b.getAttribute('data-aa-theme'));
      });

      /* ── print / export ─────────────────────────────────────────────────── */
      on($('[data-aa-print]'), 'click', function () {
        try { window.print(); } catch (e) { /* ignore */ }
      });

      /* ── scroll-spy ────────────────────────────────────────────────────── */
      function setActive(id) {
        $$('[data-aa-nav]').forEach(function (a) {
          a.classList.toggle('on', a.getAttribute('data-aa-nav') === id);
        });
      }
      if (typeof IntersectionObserver !== 'undefined') {
        var io = new IntersectionObserver(function (entries) {
          if (disposed) return;
          var visible = entries.filter(function (en) { return en.isIntersecting; });
          if (!visible.length) return;
          visible.sort(function (a, b) { return a.boundingClientRect.top - b.boundingClientRect.top; });
          setActive(visible[0].target.id);
        }, { root: null, rootMargin: '-140px 0px -70% 0px', threshold: 0 });
        SECTIONS.forEach(function (id) {
          var el = root.querySelector('#' + id);
          if (el) io.observe(el);
        });
        observers.push(io);
      }

      /* Deep-link support: honour a hash that points at one of our sections. */
      if (location.hash) {
        var id0 = location.hash.replace('#', '');
        if (SECTIONS.indexOf(id0) !== -1) setActive(id0);
      }

      /* ── in-layout smooth scroll for the sidebar links ──────────────────── */
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }
      $$('a[href^="#aa-s"]').forEach(function (a) {
        on(a, 'click', function (e) {
          var href = a.getAttribute('href');
          var target = href && root.querySelector(href);
          if (!target) return;
          e.preventDefault();
          target.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
        });
      });

      /* Re-run the spy once fonts settle so the initial active item is right. */
      if (document.fonts && document.fonts.ready) {
        document.fonts.ready.then(function () { if (!disposed) raf(function () {}); });
      }

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
